def test_regulatory_examination_frontend_bff_sse_worker_and_ui_contracts():
    root=Path(__file__).resolve().parents[2];page=(root/'frontend/app/review/regulatory-examinations/page.tsx').read_text();api=(root/'frontend/lib/api.ts').read_text();bff=(root/'frontend/app/api/reviewer/[...path]/route.ts').read_text();sse=(root/'backend/app/api/v1/review_workbench.py').read_text();runtime=(root/'backend/app/workers/production_runtime.py').read_text();helm=(root/'infra/helm/medclaimiq/values.yaml').read_text();shell=(root/'frontend/components/review/app-shell.tsx').read_text()
    for token in ['Regulatory Examination & Inquiry Response','Authority boundary','Regulatory inquiry queue','Evidence / response workspace','Independent human approve','Secure deliver']:assert token in page
    for token in ['regulatoryExaminationDashboard','buildRegulatoryExaminationEvidencePack','draftRegulatoryExaminationResponse','approveRegulatoryExaminationResponse','deliverRegulatoryExaminationResponse','regulatoryExaminationTraceability']:assert token in api
    assert 'regulatory-examinations' in bff and 'regulatory_examination.' in sse and 'regulatory-examination' in runtime and 'regulatory-examination:' in helm and 'label:"Examinations"' in shell
